(() => {
  'use strict';
  const cfg = window.SUPABASE_CONFIG || {};
  const ready = Boolean(cfg.url && cfg.anonKey && window.supabase?.createClient);
  const supa = ready ? window.supabase.createClient(cfg.url, cfg.anonKey) : null;
  const RECENT_IDS = 'snu-lab-recent-usernames-v13';
  let currentUsername = '';
  let busy = false;
  const $=(s,r=document)=>r.querySelector(s);
  const esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
  const valid=v=>/^[a-z0-9_.-]{3,40}$/.test(v);
  const recentIds=()=>{try{const x=JSON.parse(localStorage.getItem(RECENT_IDS)||'[]');return Array.isArray(x)?x:[]}catch(_){return[]}};
  const saveRecent=id=>localStorage.setItem(RECENT_IDS,JSON.stringify([id,...recentIds().filter(x=>x!==id)].slice(0,5)));
  const updateHeader=()=>{const b=$('#accountOpen');if(b){b.textContent=currentUsername?`👤 ${currentUsername}`:'로그인';b.title=currentUsername?`${currentUsername} 계정으로 로그인됨 · 클릭하면 ID 입력 화면`:'ID를 입력해 로그인';}const badge=$('#accountStateBadge');if(badge)badge.textContent=currentUsername?`로그인: ${currentUsername}`:'';};
  const rpc=async(name,args)=>{if(!supa)throw new Error('Supabase 연결이 완료되지 않았습니다.');const {data,error}=await supa.rpc(name,args);if(error)throw error;return data;};
  async function notifyRegistry(id){
    if(!ready)return {ok:false,error:'not_configured'};
    const base=String(cfg.functionsBase||`${cfg.url.replace(/\/$/,'')}/functions/v1`).replace(/\/$/,'');
    try{
      const response=await fetch(`${base}/account-registry`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:id})});
      if(!response.ok){let detail='';try{detail=await response.text()}catch(_){};return {ok:false,error:`registry_${response.status}`,detail};}
      return {ok:true};
    }catch(error){return {ok:false,error:String(error?.message||error)}}
  }
  async function login(id){id=String(id||'').trim().toLowerCase();if(!ready)throw new Error('Supabase 연결이 완료되지 않았습니다.');if(!valid(id))throw new Error('ID는 영문·숫자·._- 조합 3~40자로 입력해 주세요.');const exists=await rpc('login_lab_account',{p_username:id});if(!exists)throw new Error('가입된 ID가 아닙니다. 먼저 회원가입을 해 주세요.');currentUsername=id;saveRecent(id);updateHeader();await loadFavorites().catch(()=>{});window.dispatchEvent(new Event('snu-account-changed'));const sync=await notifyRegistry(id);if(!sync.ok)console.warn('[SNU Lab Navigator] account registry sync failed',sync);return true;}
  async function signup(id){id=String(id||'').trim().toLowerCase();if(!ready)throw new Error('Supabase 연결이 완료되지 않았습니다.');if(!valid(id))throw new Error('ID는 영문·숫자·._- 조합 3~40자로 입력해 주세요.');const created=await rpc('create_lab_account',{p_username:id});if(!created)throw new Error('이미 사용 중인 ID입니다. 다른 ID를 선택해 주세요.');currentUsername=id;saveRecent(id);updateHeader();await loadFavorites().catch(()=>{});window.dispatchEvent(new Event('snu-account-changed'));const sync=await notifyRegistry(id);if(!sync.ok)console.warn('[SNU Lab Navigator] account registry sync failed',sync);return true;}
  async function logout(){currentUsername='';updateHeader();window.dispatchEvent(new Event('snu-account-changed'));}
  async function loadFavorites(){if(!currentUsername)return [];const data=await rpc('get_lab_favorites',{p_username:currentUsername});const ids=(data||[]).map(x=>x.lab_id);localStorage.setItem('snu-lab-favorites-v1',JSON.stringify(ids));window.dispatchEvent(new Event('snu-favorites-changed'));return ids;}
  async function setFavorite(labId,enabled){if(!currentUsername)throw new Error('ID로 로그인해 주세요.');const ok=await rpc('set_lab_favorite',{p_username:currentUsername,p_lab_id:String(labId),p_enabled:Boolean(enabled)});if(!ok)throw new Error('즐겨찾기 저장에 실패했습니다.');await loadFavorites();}
  async function callGemini(body,model='gemini-3.1-flash-lite'){if(!currentUsername)throw new Error('ID로 로그인해 주세요.');const base=String(cfg.functionsBase||`${cfg.url.replace(/\/$/,'')}/functions/v1`).replace(/\/$/,'');const response=await fetch(`${base}/gemini-proxy`,{method:'POST',headers:{'Content-Type':'application/json','x-lab-username':currentUsername},body:JSON.stringify({model,body})});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.error||`Gemini 서버 오류 ${response.status}`);return {payload,model};}
  function replaceButton(selector){const old=$(selector);if(!old)return null;const copy=old.cloneNode(true);old.replaceWith(copy);return copy;}
  function render(mode='login',notice=''){if(!$('#accountDialog'))document.body.insertAdjacentHTML('beforeend','<dialog id="accountDialog" class="account-dialog"><button class="close" id="accountClose" type="button">×</button><div id="accountBody"></div></dialog>');const d=$('#accountDialog'),body=$('#accountBody'),signupMode=mode==='signup',recent=recentIds();body.innerHTML=`<h2>${signupMode?'회원가입':'로그인'}</h2><p class="account-note">개인정보와 비밀번호를 요구하지 않습니다. ${signupMode?'사용할 고유 ID를 등록합니다.':'가입한 ID를 입력하면 로그인됩니다.'}</p>${notice?`<p class="status notice-text">${esc(notice)}</p>`:''}<label>ID<input id="accountIdInput" autocomplete="off" placeholder="예: labfinder27"></label><button id="accountPrimaryGo" class="primary" type="button">${signupMode?'회원가입':'로그인'}</button><button id="accountSwitch" class="secondary" type="button">${signupMode?'로그인으로 돌아가기':'회원가입'}</button>${currentUsername?'<button id="accountLogoutGo" class="secondary" type="button">로그아웃</button>':''}<p id="accountStatus" class="status"></p>${!signupMode&&recent.length?`<div class="recent-title">최근 사용 ID</div><div class="recent-users">${recent.map(id=>`<button class="recent-user" type="button" data-id="${esc(id)}">${esc(id)}</button>`).join('')}</div>`:''}`;$('#accountClose').onclick=()=>d.close();$('#accountSwitch').onclick=()=>render(signupMode?'login':'signup');$('#accountLogoutGo')?.addEventListener('click',async()=>{await logout();render('login','로그아웃했습니다. 다시 ID를 입력해 로그인할 수 있습니다.');});body.querySelectorAll('.recent-user').forEach(b=>b.onclick=()=>{$('#accountIdInput').value=b.dataset.id;$('#accountIdInput').focus();});$('#accountPrimaryGo').onclick=async()=>{if(busy)return;busy=true;const s=$('#accountStatus'),id=$('#accountIdInput').value;$('#accountPrimaryGo').disabled=true;$('#accountSwitch').disabled=true;s.textContent=signupMode?'회원가입 중…':'로그인 중…';try{await(signupMode?signup:login)(id);d.close();}catch(e){s.textContent=e.message||'처리 중 오류가 발생했습니다.';$('#accountIdInput').focus();}finally{busy=false;$('#accountPrimaryGo').disabled=false;$('#accountSwitch').disabled=false;}};if(!d.open)d.showModal();setTimeout(()=>$('#accountIdInput')?.focus(),0);}
  function init(){updateHeader();const accountButton=replaceButton('#accountOpen');replaceButton('#welcomeConnect');replaceButton('#saveGeminiKey');if(accountButton)accountButton.onclick=()=>render('login');$('#welcomeConnect')?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();$('#welcomeDialog')?.close();render('login');});window.SnuAccount={isConfigured:()=>ready,isLoggedIn:()=>Boolean(currentUsername),isAuthReady:()=>true,open:()=>render('login'),login,signup,logout,setFavorite,loadFavorites,callGemini,getUser:()=>null,getUsername:()=>currentUsername};if(!ready)return;}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();